import React, { useEffect, useState } from "react";

function Facilities() {
  const [facilities, setFacilities] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetch("http://localhost:8081/facilities")
      .then((res) => res.json())
      .then((data) => {
        setFacilities(data);
        setLoading(false);
      })
      .catch((err) => {
        console.error("Error fetching facilities:", err);
        setLoading(false);
      });
  }, []);

  return (
    <div style={styles.page}>
      <div style={styles.card}>
        <h1 style={styles.title}>Available Facilities</h1>

        {loading ? (
          <p>Loading facilities...</p>
        ) : facilities.length === 0 ? (
          <p>No facilities found.</p>
        ) : (
          <table style={styles.table}>
            <thead>
              <tr>
                <th>Name</th>
                <th>Address</th>
                <th>City</th>
                <th>State</th>
                <th>Zip Code</th>
                <th>Slots</th>
                <th>Contact</th>
              </tr>
            </thead>
            <tbody>
              {facilities.map((facility) => (
                <tr key={facility.facilityId}>
                  <td>{facility.facilityName}</td>
                  <td>{facility.address}</td>
                  <td>{facility.city}</td>
                  <td>{facility.state}</td>
                  <td>{facility.zipCode}</td>
                  <td>{facility.totalSlots}</td>
                  <td>{facility.contactInfo || "-"}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}

const styles = {
  page: {
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    minHeight: "100vh",
    background: "linear-gradient(135deg, #2c003e, #3b0066)",
    padding: "20px",
  },
  card: {
    backgroundColor: "#fff",
    padding: "25px",
    borderRadius: "12px",
    boxShadow: "0 4px 20px rgba(0,0,0,0.15)",
    width: "90%",
    maxWidth: "900px",
    textAlign: "center",
  },
  title: {
    marginBottom: "20px",
    color: "#2c003e",
  },
  table: {
    width: "100%",
    borderCollapse: "collapse",
  },
  th: {
    backgroundColor: "#2c003e",
    color: "#fff",
    padding: "10px",
  },
  td: {
    padding: "10px",
    border: "1px solid #ddd",
  },
};

export default Facilities;
